classMembersHook:
// EEC B1 helper: TradeStation's UltimateOscillator evaluated at a lag, fresh
// from prices (EL_FEATURES `ultimateosc`, VERIFIED):
//     UO = (4*A_len1 + 2*A_len2 + A_len3) / 7
//     A_x = Sum(Close - TrueLow, x) / Sum(TrueRange, x)
//     TrueLow = min(Low, Close[1]); TrueRange = max(High, Close[1]) - TrueLow
// windows INCLUDING the bar at `lag`, each Sum accumulated NEWEST-FIRST (the
// EL Summation order). Returns the FRACTION 0..1 -- TradeStation's function
// does NOT multiply by 100. The oscillator is a function OF PRICE, so its
// series history is REAL: each lag is recomputed from the bars EL actually
// saw, not read from a zero-filled variable buffer. The min/max are between
// tick-grid prices, so plain comparisons, as in AtrProfitTarget's TrueRange
// loop.
double UoAt(Context& ctx, int lag, int n1, int n2, int n3) const {
    double buy1 = 0.0, rng1 = 0.0;
    double buy2 = 0.0, rng2 = 0.0;
    double buy3 = 0.0, rng3 = 0.0;
    int nMax = n1 > n2 ? n1 : n2;
    if (n3 > nMax) nMax = n3;
    for (int i = 0; i < nMax; ++i) {
        int j = lag + i;
        double tl = ctx.low[j] < ctx.close[j + 1] ? ctx.low[j] : ctx.close[j + 1];
        double th = ctx.high[j] > ctx.close[j + 1] ? ctx.high[j] : ctx.close[j + 1];
        double bp = ctx.close[j] - tl;
        double tr = th - tl;
        if (i < n1) { buy1 += bp; rng1 += tr; }
        if (i < n2) { buy2 += bp; rng2 += tr; }
        if (i < n3) { buy3 += bp; rng3 += tr; }
    }
    return (4 * (buy1 / rng1) + 2 * (buy2 / rng2) + buy3 / rng3) / 7;
}

preConditionHook:
// Extremes over the oscillator's own last xbars values, the current bar (lag
// 0) included. Highest/Lowest are EL SOURCE (Extremes: seeded at position 0,
// scanning 1..Length-1, strict comparison carrying the EL relational
// tolerance), so el_gt/el_lt here -- and unlike Breakout's tick-grid closes,
// the oscillator is NOT on the tick grid, so on the 0..1 fraction scale the
// absolute 2.22e-12 tolerance genuinely bites.
uoNow = UoAt(ctx, 0, (int)len1, (int)len2, (int)len3);
uoLowest = uoNow;
uoHighest = uoNow;
for (int k = 1; k < (int)xbars; ++k) {
    double v = UoAt(ctx, k, (int)len1, (int)len2, (int)len3);
    if (el_lt(v, uoLowest)) uoLowest = v;
    if (el_gt(v, uoHighest)) uoHighest = v;
}
